import{_ as a,c as e,o as d,b0 as r}from"./chunks/framework.Dmsv_Tiv.js";const n="data:image/webp;base64,",l="data:image/png;base64,",i="data:image/png;base64,",F=JSON.parse('{"title":"LV060-FLV封装简介","description":null,"frontmatter":{"title":"LV060-FLV封装简介","date":"2025-12-15T11:43:56.000Z","icon":"famicons:logo-markdown","permalink":"/sdoc/vcodec/container/126b1a7bb0743d810373cfcd","index":true,"tags":null,"categories":null,"copyright":false,"keywords":null,"cover":null,"comments":null,"mathjax":null,"top":null,"description":null,"tdoc":{"detailDate":"2025-12-15T11:43:56.984Z","fulluuid":"10373cfcd9fb46259c6125caf633e9f6","useduuid":"10373cfcd"}},"headers":[],"relativePath":"sdoc/vcodec/container/126b1a7bb0743d810373cfcd.md","filePath":"sdoc/20-视频编解码/15-封装/LV060-FLV封装简介.md","lastUpdated":1767537778000}'),g={name:"sdoc/vcodec/container/126b1a7bb0743d810373cfcd.md"};function c(o,t,A,s,p,b){return d(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="lv060-flv封装简介" tabindex="-1">LV060-FLV封装简介 <a class="header-anchor" href="#lv060-flv封装简介" aria-label="Permalink to &quot;LV060-FLV封装简介&quot;">​</a></h1><p>其实相比视频编码和传输，音视频封装应该是非常简单的知识点了。而且我们前面还学习过 RTP 打包，RTP 打包音视频数据其实一定程度上也可以算是一种封装。</p><p>音视频封装其实就是将一帧帧视频和音频数据按照对应封装的标准有组织地存放在一个文件里面，并且再存放一些额外的基础信息，比如说分辨率、采样率等信息。那到底怎么组织这些基础信息还有音视频数据呢？我们接下来先看看 FLV 是怎么做的。</p><h2 id="一、flv-简介" tabindex="-1">一、FLV 简介 <a class="header-anchor" href="#一、flv-简介" aria-label="Permalink to &quot;一、FLV 简介&quot;">​</a></h2><p>FLV(Flash Video)是 Adobe 公司推出的一种流媒体格式，它的出现有效地解决了视频文件导入 Flash 后，使导出的 SWF 文件体积庞大，不能在网络上很好的使用等缺点。由于其视频文件体积轻、封装播放简单等优点，使得其非常合适在网络上传输，目前主流的视频网站无一例外支持 FLV 流媒体格式进行视频播放。</p><img src="'+n+'" alt="img" style="zoom:25%;"><p>2020 年 12 月 31 日，Chrome 作为最后一个宣布将不再支持使用 Flash 的应用程序浏览器，这给 FLV 格式带来了巨大的冲击 。因为 FLV 格式与 Flash Player 紧密相关，随着 Flash Player 逐渐退出历史舞台，FLV 视频在浏览器中的播放支持大幅减少 。除了一些特定的视频网站（如 BiliBili、优酷等可能通过其他技术手段继续支持 FLV 播放），许多网站均停止使用 FLV 作为视频格式 。这使得 FLV 格式在网页端的应用受到了极大的限制 。</p><p>随着视频技术的发展，视频消费逐渐向 HTML5 和其他现代格式转移 。FLV 格式并不被许多新设备和现代浏览器原生支持 。例如，在一些移动设备和新型浏览器中，无法直接播放 FLV 视频，需要额外的插件或转换才能实现播放 。这使得 FLV 格式在新的技术环境下，兼容性方面的劣势逐渐凸显，其应用范围也因此受到了进一步的压缩 。</p><h2 id="二、封装格式" tabindex="-1">二、封装格式 <a class="header-anchor" href="#二、封装格式" aria-label="Permalink to &quot;二、封装格式&quot;">​</a></h2><p>FLV 是一种非常常见的音视频封装，尤其是在流媒体场景中经常用到。FLV 封装也是比较简单的封装格式，它是由一个个 Tag 组成的。Tag 又分为视频 Tag、音频 Tag 和 Script Tag，分别用来存放视频数据、音频数据和 MetaData 数据。</p><p>下图就是 FLV 的总体结构图：</p><p><img src="'+l+'" alt="image-20251215124634824"></p><p>其总体格式图如下：</p><table><tbody><tr><td></td><td align="center"> 字段 </td><td align="center"> 字节数 </td><td align="center" colspan="2"> 含义 </td></tr><tr><td align="center" rowspan="4"> FLV Header </td><td align="center"> Signature </td><td align="center"> 3 </td><td align="left" colspan="2"> 标识符, 值为 &quot;FLV&quot;(0x46 0x4c 0x66) </td></tr><tr><td align="center"> Version </td><td align="center"> 1 </td><td align="left" colspan="2"> 版本号 </td></tr><tr><td align="center"> Flags </td><td align="center"> 1 </td><td align="left" colspan="2"> 第 6 位表示音频是不是存在, 第 8 位表示视频是不是存在, 其余为 0 </td></tr><tr><td align="center"> Header size </td><td align="center"> 4 </td><td align="left" colspan="2"> 有些地方也被描述为 Data offset，表示头部大小, 一般为 9 字节 </td></tr><tr><td align="center" rowspan="10"> FLV Body </td><td align="center"> Previous Tag size </td><td align="center"> 4 </td><td align="left" colspan="2"> 前一个 Tag 的大小 </td></tr><tr><td align="center" rowspan="6"> Tag1 </td><td align="center" rowspan="6">-</td><td align="center" rowspan="5"> Tag Header </td><td align="left"> Type: 1 字节, 表示 Tag 的类型, 音频是 0x08, 视频是 0x09, Script 是 0x12 </td></tr><tr><td align="left"> Data Size : 3 字节, 表示 Tag Data 的大小 </td></tr><tr><td align="left"> Timestamp : 3 字节, 时间戳 </td></tr><tr><td align="left"> TimestampEx : 1 字节, 扩展时间戳, Timestamp 不够的时间使用 </td></tr><tr><td align="left"> StreamId : 3 字节, 值为 0 </td></tr><tr><td align="left"> Tag Data </td><td align="left"> 不同类型 Tag 的 Data 部分结构各不相同，但是 Header 的结构相同。 </td></tr><tr><td align="center"> Previous Tag size </td><td align="center"> 4 </td><td align="left" colspan="2"> 前一个 Tag 的大小 </td></tr><tr><td align="center">......</td><td align="center">......</td><td align="left" colspan="2">......</td></tr><tr><td align="center"> Previous Tag size </td><td align="center"> 4 </td><td align="left" colspan="2"> 前一个 Tag 的大小 </td></tr></tbody></table><h3 id="_1-flv-header" tabindex="-1">1. FLV Header <a class="header-anchor" href="#_1-flv-header" aria-label="Permalink to &quot;1. FLV Header&quot;">​</a></h3><p>其中，FLV Header 占用 9 个字节。前 3 个字节是文件的标识，固定是 FLV。之后的 1 个字节表示版本。在之后的 1 个字节中的第 6 位表示是否存在音频数据，第 8 位表示是否存在视频数据，其他位都为 0。最后的 4 个字节表示从文件开头到 FLV Body 开始的长度，一般就是等于 9。</p><table><tbody><tr><td></td><td align="center"> 字段 </td><td align="center"> 字节数 </td><td align="center" colspan="2"> 含义 </td></tr><tr><td align="center" rowspan="4"> FLV Header </td><td align="center"> Signature </td><td align="center"> 3 </td><td align="left" colspan="2"> 标识符, 值为 &quot;FLV&quot;(0x46 0x4c 0x66) </td></tr><tr><td align="center"> Version </td><td align="center"> 1 </td><td align="left" colspan="2"> 版本号 </td></tr><tr><td align="center"> Flags </td><td align="center"> 1 </td><td align="left" colspan="2"> 第 6 位表示音频是不是存在, 第 8 位表示视频是不是存在, 其余为 0 </td></tr><tr><td align="center"> Header size </td><td align="center"> 4 </td><td align="left" colspan="2"> 有些地方也被描述为 Data offset，表示头部大小, 一般为 9 字节 </td></tr></tbody></table><h3 id="_2-flv-body" tabindex="-1">2. FLV Body <a class="header-anchor" href="#_2-flv-body" aria-label="Permalink to &quot;2. FLV Body&quot;">​</a></h3><p>在 FLV Header 之后就是 FLV Body 了，这就是存放主要数据的地方，放置着一个个 Tag。在每一个 Tag 前面都有一个 4 字节的 Previous Tag Size，表示前一个 Tag 的大小，方便往回倒。再之后就是具体的 Tag 了。</p><p>FLV Tag 用于承载音视频数据和元数据（Metadata）。FLV 格式包含三种类型的标签：音频标签（Audio Tag）、视频标签（Video Tag）和脚本数据标签（Script Data Tag）。</p><ul><li><strong>音频标签（Audio Tag）</strong>：音频标签用于承载音频数据，如 AAC、MP3 等。音频标签包含一个音频头部（Audio Header）和一个音频负载（Audio Payload）。音频头部用于描述音频负载的编码格式、采样率、声道数等信息。</li><li><strong>视频标签（Video Tag）</strong>：视频标签用于承载视频数据，如 H.264、VP6 等。视频标签包含一个视频头部（Video Header）和一个视频负载（Video Payload）。视频头部用于描述视频负载的编码格式、帧类型等信息。</li><li><strong>脚本数据标签（Script Data Tag）</strong>：脚本数据标签用于承载元数据（Metadata），如分辨率、帧率、码率等。脚本数据标签包含一个脚本数据头部（Script Data Header）和一个脚本数据负载（Script Data Payload）。脚本数据头部用于描述脚本数据负载的类型和长度。</li></ul><p>对于不同类型的 Tag，“Tag Header”（标签头）的格式都是相同的 。Tag Header 主要包含一些通用信息，比如 TagType（1 字节，指示本 TAG 包含的数据的类型，0x08 代表音频数据，0x09 代表视频数据，0x18 代表脚本数据）、DataSize（3 字节，指示 FLV TAG 总 Data 字段的数据长度，这个长度是不包含 tag head 的长度）、Timestamp（3 字节，指示该 tag 的时间戳，单位毫秒）、TimestampExtended（1 字节，24 位不够时，本字节作为高位，时间戳变成 32 位）、StreamID（3 字节，总是 0） 。</p><p>而 “Tag Body”（标签体）的格式则会因 Tag 类型的不同而有所差异 。需要注意的是时间戳的时间是 dts 解码时间。</p><h4 id="_2-1-tag-header" tabindex="-1">2.1 Tag Header <a class="header-anchor" href="#_2-1-tag-header" aria-label="Permalink to &quot;2.1 Tag Header&quot;">​</a></h4><p>Tag 是由 Tag Header 和 Tag Data 组成，其中 Tag Header 占用 11 个字节：</p><table><tbody><tr><td align="center" rowspan="5"> Tag Header </td><td align="left"> Type: 1 字节, 表示 Tag 的类型, 音频是 0x08, 视频是 0x09, Script 是 0x12 </td></tr><tr><td align="left"> Data Size : 3 字节, 表示 Tag Data 的大小, FLV TAG 总 Data 字段的数据长度，这个长度是不包含 tag head 的长度 </td></tr><tr><td align="left"> Timestamp : 3 字节, 时间戳 </td></tr><tr><td align="left"> TimestampEx : 1 字节, 扩展时间戳, Timestamp 不够的时间使用,24 位不够时，本字节作为高位，时间戳变成 32 位 </td></tr><tr><td align="left"> StreamId : 3 字节, 值为 0 </td></tr></tbody></table> **其中最重要的是时间戳，因为播放的速度还有音视频同步都需要依赖这个时间戳的值。** 时间戳占用 3\\~4 字节，如果 3 字节不够的话，则需要使用 1 字节的扩展时间戳作为时间戳的高 8 位。还需要注意的一个点就是，时间戳的单位是 ms。RTP 的时间戳单位是 1/90000 秒，MP4 的时间戳是可以自定义的。这个时间戳的单位也是至关重要的，不要弄错了。 <h4 id="_2-2-tag-data" tabindex="-1">2.2 Tag Data <a class="header-anchor" href="#_2-2-tag-data" aria-label="Permalink to &quot;2.2 Tag Data&quot;">​</a></h4><p>接下来就是 Tag Data 数据了。Tag Data 有 Script、音频和视频。</p><h5 id="_2-2-1-script-tag-data" tabindex="-1">2.2.1 Script Tag Data <a class="header-anchor" href="#_2-2-1-script-tag-data" aria-label="Permalink to &quot;2.2.1  Script Tag Data&quot;">​</a></h5><p>首先来看一下 Script Tag 的 Data。这个 Tag 存放的是 MetaData 数据，主要包括宽、高、时长、采样率等基础信息。这些信息就像视频的名片，方便对视频进行分类、搜索和管理 。同时，脚本信息则可以实现一些简单的交互操作，比如在视频播放过程中触发特定的动作等 。它为视频增添了更多的信息维度和交互性，提升了用户与视频的互动体验 。</p><p>Script Data 使用 2 个 AMF 包来存放信息：</p><p><img src="'+i+'" alt="image-20251215165807816"></p><p>第一个 AMF 包是 onMetaData 包。第 1 个字节表示的是 AMF 包的类型，一般是字符串类型，值是 0x02，之后是 2 字节的长度，一般长度总是 10，值是 0x000A。之后就是 10 字节长度字符串了，值是 onMetaData。</p><p>第二个 AMF 包的第一个字节是数组类型，值是 0x08，紧接着 4 个字节为数组元素的个数。后面即为各数组元素的封装，数组元素为元素名称和值组成的对。常见的数组元素如下表所示：</p><table><tbody><tr><td align="center"> 元素类型 </td> <td align="center"> 元素的意义 </td></tr><tr><td align="center"> duration </td> <td align="center"> 时长 </td></tr><tr><td align="center"> file size </td> <td align="center"> 文件大小 </td></tr><tr><td align="center"> width </td> <td align="center"> 视频的宽 </td></tr><tr><td align="center"> height </td> <td align="center"> 视频的高 </td></tr><tr><td align="center"> video data rate </td> <td align="center"> 视频码率 </td></tr><tr><td align="center"> frame rate </td> <td align="center"> 视频帧率 </td></tr><tr><td align="center"> video codec id </td> <td align="center"> 视频编码类型 </td></tr><tr><td align="center"> audio sample rate </td> <td align="center"> 音频采样率 </td></tr><tr><td align="center"> audio sample size </td> <td align="center"> 音频的位宽 </td></tr><tr><td align="center"> audio data rate </td> <td align="center"> 音频编码码率 </td></tr><tr><td align="center"> stereo </td> <td align="center"> 是不是立体声 </td></tr><tr><td align="center"> audio codec id </td> <td align="center"> 音频编码类型 </td></tr></tbody></table> ##### 2.2.2 Audio Tag Data <p>音频 Tag Data 的第一个字节表示音频的编码方式、采样率和位宽等信息，如下所示。之后就是音频数据了。</p><table><tbody><tr><td align="center"> 字段 </td> <td align="center"> 占用大小 </td> <td align="left"> 说明 </td></tr><tr><td align="center"> 音频编码类型 </td> <td align="center"> 4bits </td> <td align="left"> 2 表示 mp3、10 表示 aac </td></tr><tr><td align="center"> 采样率 </td> <td align="center"> 2bits </td> <td align="left"> 0 表示 5.5kHz、1 表示 11kHz、2 表示 22kHz、3 表示 44kHz </td></tr><tr><td align="center"> 位宽 </td> <td align="center"> 1bit </td> <td align="left"> 0 表示 8 位、1 表示 16 位 </td></tr><tr><td align="center"> 声道数 </td> <td align="center"> 1bit </td> <td align="left"> 0 表示单声道、1 表示双声道 </td></tr></tbody></table><p>第二个字节开始为音频数据。</p><table><tbody><tr><td align="center" width="100px"> 字段 </td> <td align="center" width="100px"> 占用大小 </td> <td align="center"> 说明 </td></tr><tr><td align="center"> 音频数据 </td> <td align="center"> n 字节 </td> <td align="left"> AudioTagBody 存储的数据根据当前格式不同而不同。如果是 PCM 线性数据，存储的时候每个按 16bit 小端存储，有符号。如果是 AAC，则存储的数据是 AAC AUDIO DATA，否则为线性数组 </td></tr></tbody></table><h5 id="_2-2-3-video-tag-data" tabindex="-1">2.2.3 Video Tag Data <a class="header-anchor" href="#_2-2-3-video-tag-data" aria-label="Permalink to &quot;2.2.3 Video Tag Data&quot;">​</a></h5><p>视频 Tag 的第 1 个字节包含了这个 Tag 的视频帧类型和视频编码方式，格式如下图：</p><table><tbody><tr><td align="center"> 字段 </td> <td align="center"> 占用大小 </td> <td align="left"> 说明 </td></tr><tr><td align="center"> 视频帧类型 </td> <td align="center"> 4bits </td> <td align="left"> 1 表示关键帧、2 表示非关键帧 </td></tr><tr><td align="center"> 视频编码类型 </td> <td align="center"> 4bits </td> <td align="left"> 7 表示 H264(AVC)</td></tr></tbody></table><p>对于 H264 数据，紧接着会有 4 字节的 AVC Packet Type 格式，如下图所示：</p><table><tbody><tr><td align="center"> 字段 </td> <td align="center"> 占用大小 </td> <td align="left"> 说明 </td></tr><tr><td align="center"> AVC 包类型 </td> <td align="center"> 1 字节 </td> <td align="left"> 0 表示序列头（包含 SPS、PPS）、1 表示 NALU </td></tr><tr><td align="center"> CTS </td> <td align="center"> 3 字节 </td> <td align="left"> 如果包类型是 0 则为 0。如果包类型是 1 则表示 cts，cts = pts-dts </td></tr></tbody></table> **其中最重要的就是 CTS。** 这个是什么意思呢？ <p>pts：显示时间，也就是接收方在显示器显示这帧的时间。单位为 1/90000 秒。</p><p>dts：解码时间，也就是 rtp 包中传输的时间戳，表明解码的顺序。单位单位为 1/90000 秒。——根据后面的理解，pts 就是标准中的 CompositionTime</p><p>cts 偏移：cts = (pts - dts) / 90 。cts 的单位是毫秒。</p><p>pts 和 dts 的时间不一样，应该只出现在含有 B 帧的情况下，也就是 profile main 以上。baseline 是没有这个问题的，baseline 的 pts 和 dts 一直相同，所以 cts 一直为 0。因为 H264 有 B 帧这种类型，涉及到显示时间戳 PTS 和解码时间戳 DTS。前面 Tag Header 里的时间戳就是 DTS，PTS 等于 DTS + CTS，这个需要注意一下。接下来就是存放具体的视频数据。</p><p>如果 AVC 包类型是 0，则数据格式如下图所示：</p><table><tbody><tr><td align="center">字段 </td><td align="center">占用大小 </td><td align="center">说明</td></tr><tr><td align="center">版本号 </td><td align="center"> 1字节 </td><td align="center"> 版本号为1</td></tr><tr><td align="center">AVC Profile Indication</td><td align="center"> 1字节 </td><td align="center"> H264 Profile</td></tr><tr><td align="center">Profile Compatibility </td><td align="center"> 1字节 </td><td align="center"></td></tr><tr><td align="center">AVC Level Indication </td><td align="center"> 1字节 </td><td align="center"> H264 Level</td></tr><tr><td align="center">Length Size Minus One </td><td align="center"> 1字节 </td><td align="center"></td></tr><tr><td align="center">SPS的个数 </td><td align="center"> 1字节 </td><td align="center"></td></tr><tr><td align="center">SPS的大小 </td><td align="center"> 2字节 </td><td align="center"></td></tr><tr><td align="center">SPS </td><td align="center"> 具体大小前面计算得到</td><td align="center"></td></tr><tr><td align="center">PPS的个数 </td><td align="center"> 1字节 </td><td align="center"></td></tr><tr><td align="center">PPS的大小 </td><td align="center"> 2字节 </td><td align="center"></td></tr><tr><td align="center">PPS </td><td align="center"> 具体大小前面计算得到</td><td align="center"></td></tr></tbody></table><p>如果 AVC 包类型为 1，则数据格式如下图所示：</p><table><tbody><tr><td align="center"> 字段 </td> <td align="center"> 占用大小 </td></tr><tr><td align="center"> NALU 长度 </td> <td align="center"> 4 字节 </td></tr><tr><td align="center"> NALU 数据 </td> <td align="center"> 具体大小由前面计算得到 </td></tr></tbody></table> 这就是 FLV 封装。 <blockquote><p>参考资料：</p><p><a href="https://jiangyaos-note.readthedocs.io/zh-cn/latest/docs/%E9%9F%B3%E8%A7%86%E9%A2%91/%E5%B0%81%E8%A3%85%E6%A0%BC%E5%BC%8F%E4%B9%8BFLV%E6%A0%BC%E5%BC%8F.html" target="_blank" rel="noreferrer">封装格式之 FLV 格式 — MyNote release 文档</a></p><p><a href="https://zhuanlan.zhihu.com/p/455989901" target="_blank" rel="noreferrer">(5 封私信) 音视频基础：FLV 封装格式介绍及解析 - 知乎</a></p><p><a href="https://blog.csdn.net/2301_76564925/article/details/147672343" target="_blank" rel="noreferrer">深入解析 FLV 封装格式：流媒体世界的轻骑兵-CSDN 博客</a></p><p><a href="https://zhuanlan.zhihu.com/p/654246696" target="_blank" rel="noreferrer">(5 封私信) FLV 封装格式详解 - 知乎</a></p></blockquote>',57)])])}const f=a(g,[["render",c]]);export{F as __pageData,f as default};
